insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_105_v1'
from (values
('127.763.d.1.A',3,'A student reads about scribes, tax collectors and couriers who ran the ancient Egyptian and Chinese empires. This explores the ancient history of:','["public administration", "space travel", "pop music", "sports medicine"]'::jsonb,0,'Ancient states relied on administrators.','original'),
('127.763.d.1.A',4,'Ancient empires such as China used trained officials to:','["design video games", "collect taxes and run the state", "publish websites", "operate airlines"]'::jsonb,1,'Early public administration.','original'),
('127.763.d.1.B',3,'A class compares a paper-ledger tax office from the past with a modern online filing system and asks if citizens are better served. This considers whether:','["tools never change", "service is unimportant", "current practices of public administration are improvements", "old methods always win"]'::jsonb,2,'Evaluate modern practice against the past.','original'),
('127.763.d.1.B',4,'An example of a modern improvement in public administration is:','["lost records", "longer lines", "slower paper forms", "online services that cut waiting time"]'::jsonb,3,'Technology improves service.','original'),
('127.763.d.1.C',3,'Citizens complain that getting a permit means endless forms and many offices. A student explains the term for this system of rules and offices and why people often view it negatively. This explains:','["bureaucracy and public perception of it", "a farm tool", "a type of music", "a sports trophy"]'::jsonb,0,'Bureaucracy means rule-bound administration.','original'),
('127.763.d.1.C',4,'A bureaucracy is best described as:','["a village festival", "an organization with specialized offices and set rules", "a single ruler", "a trade fair"]'::jsonb,1,'Hierarchy, rules and specialization.','original'),
('127.763.d.1.D',3,'Staff morale drops when a public agency is widely distrusted, and its director adopts a stricter style. This analyzes the effects of:','["good weather on leaders", "music on managers", "poor public perception on leadership style", "lunch on leaders"]'::jsonb,2,'Perception shapes how leaders lead.','original'),
('127.763.d.1.D',4,'A leader facing public distrust can rebuild confidence by:','["avoiding the media", "hiding information", "ignoring complaints", "being transparent and responsive"]'::jsonb,3,'Transparency builds trust.','original'),
('127.763.d.1.E',3,'A scholar compares the idea that many groups compete for influence with theories about how power shifts to new issues and how technology changes it. This analyzes:','["political pluralism and related hypotheses", "pasta cooking", "farm markets", "sports training"]'::jsonb,0,'Pluralism and related ideas explain power.','original'),
('127.763.d.1.E',4,'Political pluralism holds that political power is:','["held by one party only", "shared among many competing groups", "held by one person", "held by no one"]'::jsonb,1,'Many groups compete.','original'),
('127.763.d.1.F',3,'A city manager reviews whether departments meet output goals, stay inside the budget and serve citizens well. This recognizes that public management involves evaluating:','["plants, seeds and soil", "fashion, colors and sizes", "productivity, budgets and services", "songs, beats and tempos"]'::jsonb,2,'Management measures results.','original'),
('127.763.d.1.F',4,'A key way public managers judge a program''s success is by comparing:','["logos to slogans", "slogans to posters", "colors to fonts", "results to goals and costs"]'::jsonb,3,'Compare outcomes to targets.','original'),
('127.763.d.1.G',3,'A case study describes an official who steered a contract to a relative. A student explains why this is an ethics problem. This researches and explains:','["ethics issues in public administration", "car repair", "pet care", "weather reports"]'::jsonb,0,'Conflicts of interest are ethical issues.','original'),
('127.763.d.1.G',4,'Giving a contract to a relative without competition is an example of:','["audit success", "nepotism and a conflict of interest", "open government", "fair bidding"]'::jsonb,1,'Nepotism undermines fairness.','original'),
('127.763.d.2.A',3,'A student charts how two parties and an environmental group view a clean-water bill, noting where they differ. This compares:','["routes of different buses", "outfits of different teams", "points of view of parties and interest groups on important issues", "recipes of different chefs"]'::jsonb,2,'Groups hold different views.','original'),
('127.763.d.2.A',4,'Parties and interest groups often differ on issues because they:','["share identical goals", "have no members", "avoid all debate", "represent different values and constituencies"]'::jsonb,3,'Different interests.','original'),
('127.763.d.2.B',3,'A teacher explains that without free speech and a free press, citizens could not criticize leaders or learn the facts. This analyzes the importance of:','["free speech and press in a democratic society", "free shipping", "free parking", "free lunches"]'::jsonb,0,'They enable informed self-government.','original'),
('127.763.d.2.B',4,'A free press helps a democracy by:','["hiding facts", "informing citizens and holding leaders accountable", "controlling elections", "silencing critics"]'::jsonb,1,'Watchdog role.','original'),
('127.763.d.2.C',3,'Students are asked to state and support their own view on a current debate with evidence and respectful language. This expresses a student''s point of view on:','["a favorite snack", "a hair style", "an issue of contemporary interest in the field of government", "a vacation plan"]'::jsonb,2,'Informed opinions are supported by evidence.','original'),
('127.763.d.2.C',4,'A well-supported opinion on a public issue should include:','["personal insults", "only volume", "no facts", "clear reasons and evidence"]'::jsonb,3,'Reasons and evidence.','original'),
('127.763.d.3.A',3,'A timeline traces Westphalia in 1648, the balance-of-power era and the League of Nations. This examines the historical development of:','["the international system", "the school calendar", "the train timetable", "the postal route"]'::jsonb,0,'The system of states evolved.','original'),
('127.763.d.3.A',4,'The Peace of Westphalia (1648) is often seen as a start of the modern system of:','["empires with no borders", "sovereign nation-states", "global corporations", "city leagues only"]'::jsonb,1,'Westphalian sovereignty.','original'),
('127.763.d.3.B',3,'A chart contrasts a Europe-centered balance of power, the period between the world wars and the Cold War''s two blocs. This compares:','["three clothing sizes", "three art styles", "the classical, transitional and bipolar international systems", "three cooking styles"]'::jsonb,2,'Systems differ in who holds power.','original'),
('127.763.d.3.B',4,'During the Cold War, the international system was mainly shaped by:','["one world government", "no major powers", "many equal powers", "two superpowers, the U.S. and the Soviet Union"]'::jsonb,3,'Bipolar system.','original'),
('127.763.d.3.C',3,'A class studies how states, alliances and international bodies each act when a crisis erupts and how they respond to each other. This researches:','["national actors and international interactions", "local weather", "sports scores", "family trees"]'::jsonb,0,'Actors interact.','original'),
('127.763.d.3.C',4,'In international relations, a nation-state is an example of a:','["trade fair", "state actor", "private hobby", "weather system"]'::jsonb,1,'States are primary actors.','original'),
('127.763.d.3.D',3,'A student explains that leaders weigh costs and benefits, rank goals and pick the option with the best expected result. This examines the:','["random walk model", "fashion model", "rational actor model", "farm model"]'::jsonb,2,'Rational choice weighs options.','original'),
('127.763.d.3.D',4,'The rational actor model assumes that a government:','["acts without thought", "acts only by chance", "never chooses", "acts to maximize its goals after weighing options"]'::jsonb,3,'Goal-driven choice.','original'),
('127.763.d.3.E',3,'When a border dispute flares, a country debates talks, sanctions, alliances or force before choosing. This analyzes what a nation-state does when:','["faced with a problem that requires resolution", "it is on vacation", "it has no leaders", "there is no problem"]'::jsonb,0,'States choose among tools.','original'),
('127.763.d.3.E',4,'Before resorting to force, a country usually tries tools such as:','["ignoring issues", "diplomacy and economic pressure", "closing borders to all", "only silence"]'::jsonb,1,'Escalation ladder.','original'),
('127.763.d.3.F',3,'A student asks whether it is right for a nation to back a friendly dictator for strategic gain. This makes observations about:','["ethics in gaming", "ethics in fashion", "ethics in foreign policy", "ethics in cooking"]'::jsonb,2,'Foreign policy raises ethical questions.','original'),
('127.763.d.3.F',4,'An ethical dilemma in foreign policy arises when a country must balance:','["cost with color", "speed with fonts", "mood with lunch", "national interests with human rights"]'::jsonb,3,'Interests versus values.','original'),
('127.763.d.3.G',3,'Cold War choices such as arming rebel groups raised questions of right and wrong versus strategy. This draws conclusions about:','["the role of morality in decision making", "the role of fashion", "the role of weather", "the role of music"]'::jsonb,0,'Morality competes with strategy.','original'),
('127.763.d.3.G',4,'Debating whether to support a regime that violates rights for strategic reasons shows tension between:','["rain and sun", "morality and national interest", "breakfast and lunch", "art and sport"]'::jsonb,1,'Principle versus pragmatism.','original'),
('127.763.d.4.A',3,'In ancient times, rulers sent messengers to other kingdoms and today countries keep standing embassies. This compares:','["ancient pottery with modern pottery", "old roads with new roads", "ancient emissaries with current embassies", "old songs with new songs"]'::jsonb,2,'Emissaries evolved into embassies.','original'),
('127.763.d.4.A',4,'A key difference between ancient emissaries and modern embassies is that embassies are:','["unofficial", "one-time visits", "unprotected", "permanent offices with a staff"]'::jsonb,3,'Permanent missions.','original'),
('127.763.d.4.B',3,'An ambassador represents the president abroad while an embassy staff handles visas, trade and reports. This identifies:','["embassy and ambassador roles in international relations", "bus driver roles", "teacher roles", "bakery roles"]'::jsonb,0,'Embassies support diplomacy.','original'),
('127.763.d.4.B',4,'The chief representative of a country to another country is the:','["governor", "ambassador", "mayor", "senator"]'::jsonb,1,'Ambassadors lead missions.','original'),
('127.763.d.4.C',3,'A guide lists talks held openly, talks held in private, talks among many states and talks between two. This distinguishes types of diplomacy such as:','["hot versus cold drinks", "fast versus slow cars", "public versus secret, multilateral versus bilateral", "big versus small shoes"]'::jsonb,2,'Diplomacy takes different forms.','original'),
('127.763.d.4.C',4,'Talks involving just two countries are called:','["public relations", "secret diplomacy only", "multilateral diplomacy", "bilateral diplomacy"]'::jsonb,3,'Bilateral = two parties.','original'),
('127.763.d.4.D',3,'Two countries negotiate a fishing treaty, each weighing what the other might concede. A student models the choices using the idea of strategic interaction. This uses:','["bargaining and game theory to solve problems", "racing and jumping", "painting and singing", "baking and decorating"]'::jsonb,0,'Game theory models choices.','original'),
('127.763.d.4.D',4,'In game theory, a player chooses strategies by considering:','["nothing at all", "what other players are likely to do", "only the weather", "only past meals"]'::jsonb,1,'Strategic thinking.','original'),
('127.763.d.4.E',3,'When talks fail, a national government may deploy its military while a state guard supports local emergencies. This recognizes national versus state approaches to:','["road signs", "tax forms", "armed force when diplomacy breaks down", "school lunches"]'::jsonb,2,'Armed force follows constitutional lines.','original'),
('127.763.d.4.E',4,'In the U.S., the power to wage war abroad rests mainly with the:','["school boards", "city councils", "county fairs", "national government"]'::jsonb,3,'Federal responsibility.','original'),
('127.763.d.4.F',3,'A scholar describes naval blockades and troop buildups short of fighting, then studies why wars begin and what they cost. This analyzes:','["force without war, causes of war and consequences of war", "food without taste", "art without color", "music without words"]'::jsonb,0,'Coercion, causes, consequences.','original'),
('127.763.d.4.F',4,'A blockade or troop buildup used to pressure another state without fighting is an example of:','["a trade fair", "force without war", "total war", "a peace treaty"]'::jsonb,1,'Coercive diplomacy.','original'),
('127.763.d.4.G',3,'Treaties, customary rules and refugee conventions guide how nations treat each other''s citizens and borders. This analyzes the role of:','["comic books in schools", "pop charts in radio", "international law in treaties, customs, immigration and human rights", "crop circles in farms"]'::jsonb,2,'International law structures behavior.','original'),
('127.763.d.4.G',4,'A treaty is a:','["private diary", "local ordinance", "tax form", "formal written agreement between nations"]'::jsonb,3,'Treaties bind states.','original'),
('127.763.d.5.A',3,'A student lists the United Nations and NATO as groups of governments, and the Red Cross and Doctors Without Borders as groups of private volunteers. This identifies:','["governmental and non-governmental international organizations", "clubs at school", "city parks", "local stores"]'::jsonb,0,'IGOs and NGOs.','original'),
('127.763.d.5.A',4,'A non-governmental organization (NGO) is one that:','["is a state agency", "is not run by a government", "sets national laws", "is run by the army"]'::jsonb,1,'NGOs are independent.','original'),
('127.763.d.5.B',3,'A report explains how the UN Security Council votes, how the General Assembly debates and how agencies deliver aid. This explores the methods and function of:','["bake sales", "parades", "international governmental organizations", "school clubs"]'::jsonb,2,'IGOs operate through bodies and votes.','original'),
('127.763.d.5.B',4,'The United Nations was created mainly to:','["replace national governments", "create a single army", "end all trade", "promote peace and cooperation among nations"]'::jsonb,3,'UN purpose.','original'),
('127.763.d.5.C',3,'A team drafts a plan for limiting nuclear stockpiles that includes inspections and treaty steps. This proposes a solution to an international problem such as:','["arms control", "recipe sharing", "weather forecasts", "sports rivalry"]'::jsonb,0,'Arms control needs verification.','original'),
('127.763.d.5.C',4,'A realistic proposal for an international problem should include:','["only a slogan", "who will act, how, and how compliance will be checked", "only a complaint", "no timeline"]'::jsonb,1,'Concrete steps and verification.','original'),
('127.763.d.6.A',3,'A class examines who can make binding rules, what freedoms people hold and what duties they owe, to judge how well a government works. This examines concepts of:','["songs, notes and beats", "lunch, recess and bells", "authority, rights and responsibilities", "maps, keys and scales"]'::jsonb,2,'Core civic concepts.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_105_v1'
from (values
('127.763.d.6.A',4,'Authority in government means the:','["ability to avoid taxes", "power to hide", "right to ignore laws", "legitimate power to make and enforce decisions"]'::jsonb,3,'Authority is legitimate power.','original'),
('127.763.d.6.B',3,'A student explains that the national government defends the country, manages trade and conducts foreign affairs, while also serving citizens at home. This explains major responsibilities for:','["domestic and foreign affairs", "local games", "bake offs", "pet shows"]'::jsonb,0,'Federal responsibilities.','original'),
('127.763.d.6.B',4,'Which responsibility belongs primarily to the national government?','["trash collection", "national defense", "local parks", "school lunches"]'::jsonb,1,'Defense is federal.','original'),
('127.763.d.6.C',3,'In a mock summit, students practice listening, asking questions and rephrasing to keep a discussion productive. This practices:','["bubble drawing", "silent reading only", "communication techniques for exchanging ideas and debate", "timed running"]'::jsonb,2,'Good communication supports debate.','original'),
('127.763.d.6.C',4,'A good technique for productive debate is to:','["interrupt", "avoid eye contact", "shout", "restate the other side''s point before responding"]'::jsonb,3,'Active listening.','original'),
('127.763.d.6.D',3,'A student tracks how a global trade pact, a federal rule, a state law and a city ordinance each affect one local business. This interprets the impact of:','["politics at several levels on the daily lives of citizens", "comics on weather", "sports on rain", "songs on laws"]'::jsonb,0,'Politics at every level affects daily life.','original'),
('127.763.d.6.D',4,'A city zoning rule can affect a citizen''s daily life by:','["closing the state", "determining where businesses and homes may be built", "rewriting the constitution", "changing the calendar"]'::jsonb,1,'Local rules affect daily life.','original'),
('127.764.d.1.A',3,'A consular trainee explains visa steps clearly to a visitor in person and then writes a short summary of the discussion. This communicates:','["only by gesture", "only by silence", "effectively using oral and written skills", "only by text emoji"]'::jsonb,2,'Clear speaking and writing are core skills.','original'),
('127.764.d.1.A',4,'A good written report for a supervisor should be:','["filled with slang", "unorganized", "vague and long", "clear, accurate and concise"]'::jsonb,3,'Professional writing.','original'),
('127.764.d.1.B',3,'Staff in an embassy section share tasks, trade updates and help each other meet a deadline. This demonstrates:','["collaboration skills through teamwork", "working alone only", "blaming others", "avoiding tasks"]'::jsonb,0,'Teamwork gets results.','original'),
('127.764.d.1.B',4,'Effective teamwork on a project requires members to:','["work against each other", "share information and support one another", "hoard information", "skip meetings"]'::jsonb,1,'Collaboration.','original'),
('127.764.d.1.C',3,'An attaché dresses neatly, arrives on time and speaks respectfully at a formal reception. This demonstrates:','["rudeness", "casual behavior", "professionalism appropriate for the workplace", "careless dress"]'::jsonb,2,'Professional conduct.','original'),
('127.764.d.1.C',4,'Professional behavior at an embassy event includes:','["loud complaints", "ignoring guests", "late arrival", "courtesy and appropriate dress"]'::jsonb,3,'Courtesy matters.','original'),
('127.764.d.1.D',3,'A clerk completes every assigned filing task on time without being reminded and asks what else is needed. This demonstrates:','["a positive, productive work ethic", "wasting time", "avoiding responsibility", "a low effort attitude"]'::jsonb,0,'Work ethic means dependable effort.','original'),
('127.764.d.1.D',4,'A new clerk is handed a list of filing tasks for the day. Which behavior best reflects a strong work ethic?','["ignoring directions", "completing assigned tasks as directed", "leaving early", "doing only easy work"]'::jsonb,1,'Follow through.','original'),
('127.764.d.1.E',3,'An officer is offered a gift to speed a visa and refuses, reports it and follows all rules. This shows integrity by:','["breaking the rules", "hiding the offer", "choosing the ethical course and complying with regulations", "accepting the gift"]'::jsonb,2,'Integrity means doing right.','original'),
('127.764.d.1.E',4,'If someone offers a bribe to a government employee, the ethical response is to:','["ask for more", "keep it secret", "accept it", "refuse it and report it"]'::jsonb,3,'Report bribes.','original'),
('127.764.d.1.F',3,'A staffer ranks urgent cables first, follows the daily schedule and meets every deadline. This demonstrates:','["time-management skills", "poor planning", "random order", "procrastination"]'::jsonb,0,'Prioritize and schedule.','original'),
('127.764.d.1.F',4,'To manage time well, a worker should first:','["wait until the end", "prioritize tasks by urgency and importance", "ignore deadlines", "do tasks at random"]'::jsonb,1,'Prioritizing.','original'),
('127.764.d.2.A',3,'A public affairs officer briefs a foreign ministry on a new U.S. exchange policy and answers questions. This demonstrates the ability to provide:','["recipes only", "sports scores only", "host-country officials with information on U.S. policy", "tourist maps only"]'::jsonb,2,'Diplomats inform host governments.','original'),
('127.764.d.2.A',4,'When briefing host-country officials, a diplomat should be:','["silent", "misleading", "vague", "accurate and clear about U.S. positions"]'::jsonb,3,'Accuracy builds trust.','original'),
('127.764.d.2.B',3,'A program office plans to bring student leaders from another country to the U.S. so they can learn about its culture. This demonstrates an understanding of:','["organizing exchange programs", "cancelling visits", "closing programs", "ending contact"]'::jsonb,0,'Exchanges build understanding.','original'),
('127.764.d.2.B',4,'A main purpose of an exchange program is to:','["spread rumors", "build mutual understanding between peoples", "increase tariffs", "reduce contact"]'::jsonb,1,'Exchanges promote goodwill.','original'),
('127.764.d.2.C',3,'Analysts review whether U.S. aid for schools in a partner country improved enrollment and goodwill. This analyzes the effectiveness of:','["bake sales", "school fundraisers", "foreign support programs and other U.S. efforts", "local contests"]'::jsonb,2,'Evaluate outcomes.','original'),
('127.764.d.2.C',4,'To judge whether a foreign aid program works, analysts compare:','["colors to fonts", "slogans to songs", "budgets to weather", "results to stated goals"]'::jsonb,3,'Compare outcomes to goals.','original'),
('127.764.d.2.D',3,'At a press briefing, an official explains a new U.S. policy accurately and politely, then answers a reporter''s follow-up. This shows how to:','["address and respond to media personnel on matters of U.S. policy", "ignore questions", "argue with reporters", "avoid reporters"]'::jsonb,0,'Respond professionally.','original'),
('127.764.d.2.D',4,'When a reporter asks about something the official does not know, the best response is to:','["guess", "say so and offer to follow up", "make up an answer", "walk out"]'::jsonb,1,'Honesty and follow-up.','original'),
('127.764.d.2.E',3,'After a diplomatic incident, a spokesperson stays calm, sticks to verified facts and avoids speculation when a reporter pushes. This shows how to respond to media on matters of:','["weekend plans", "movie ratings", "U.S. policy during a sensitive situation", "menu choices"]'::jsonb,2,'Stay factual in sensitive moments.','original'),
('127.764.d.2.E',4,'During a sensitive media exchange, a diplomat should avoid:','["staying calm", "being courteous", "telling the truth", "speculating beyond verified facts"]'::jsonb,3,'Avoid speculation.','original'),
('127.764.d.3.A',3,'After a U.S. delegation visit, local officials praise the aid but ask for more training support. This describes:','["host-country responses to U.S. programs and official visits", "weather reports", "sports scores", "menu choices"]'::jsonb,0,'Reports capture reactions.','original'),
('127.764.d.3.A',4,'A diplomatic report on a visit should include:','["only menu choices", "how host-country officials and citizens responded", "only travel times", "only weather"]'::jsonb,1,'Capture reactions.','original'),
('127.764.d.3.B',3,'Staff write a report on how tourists and movies from the U.S. change attitudes and fashion in a host city. This analyzes the impact of:','["rain on streets", "trains on tracks", "American travelers and popular culture on a host country", "roads on maps"]'::jsonb,2,'Culture shapes impressions.','original'),
('127.764.d.3.B',4,'American popular culture abroad can influence a host country''s:','["rivers", "time zone", "mountain heights", "views of the United States"]'::jsonb,3,'Soft power.','original'),
('127.764.d.3.C',3,'After an earthquake, embassy staff review how quickly local authorities responded and what support was requested. This assesses:','["the impact of host-country responses to catastrophic events", "last year''s festival", "a sports game", "a school dance"]'::jsonb,0,'Assessments guide aid.','original'),
('127.764.d.3.C',4,'After a catastrophe abroad, an embassy''s first priority is typically:','["sports events", "the safety and assistance of U.S. citizens", "trade fairs", "tourism ads"]'::jsonb,1,'Protect citizens.','original'),
('127.764.d.4.A',3,'A consular officer checks an applicant''s purpose of travel, ties to home and documents against U.S. law to decide on a visa. This applies:','["menu rules", "sports rules", "immigration laws and regulations to determine eligibility", "school rules"]'::jsonb,2,'Eligibility follows law.','original'),
('127.764.d.4.A',4,'Consular officers decide visa eligibility by applying:','["rumors", "personal feelings", "coin tosses", "U.S. immigration laws and regulations"]'::jsonb,3,'Law governs decisions.','original'),
('127.764.d.4.B',3,'A visa is denied because the applicant provided false information on the form. This explains:','["grounds for refusal of visas", "grounds for sports", "grounds for parties", "grounds for school trips"]'::jsonb,0,'Fraud is a ground for refusal.','original'),
('127.764.d.4.B',4,'Which is a common ground for refusing a visa?','["paying the fee", "misrepresenting facts on the application", "showing proper papers", "listing accurate facts"]'::jsonb,1,'Misrepresentation.','original'),
('127.764.d.4.C',3,'An officer searches treaties, country records and security databases to confirm the rules that apply to an applicant. This researches:','["family photos", "sports cards", "documents and databases on U.S. and host-country laws and regulations", "local recipes"]'::jsonb,2,'Research ensures correct decisions.','original'),
('127.764.d.4.C',4,'Before making a ruling, consular staff should consult:','["advertisements", "guesses", "gossip", "official laws and verified databases"]'::jsonb,3,'Use authoritative sources.','original'),
('127.764.d.4.D',3,'A staffer checks passports, birth certificates and fingerprints before issuing a travel document. This applies:','["identification and documentation procedures", "cooking procedures", "decorating procedures", "drawing procedures"]'::jsonb,0,'Verify identity carefully.','original'),
('127.764.d.4.D',4,'Verifying an identity document is important because it:','["wastes time", "prevents fraud and protects security", "hides identity", "speeds mistakes"]'::jsonb,1,'Verification stops fraud.','original'),
('127.764.d.5.A',3,'In a simulation, students negotiate with a mock host government over tax exemptions, reciprocal treatment and diplomatic privileges. This models:','["a relay race", "a bake sale", "negotiations on reciprocity, taxation and diplomatic privileges", "a card game"]'::jsonb,2,'Practice negotiating.','original'),
('127.764.d.5.A',4,'Reciprocity in diplomacy means:','["one side always wins", "only one side acts", "no rules apply", "each country gives the other equal treatment"]'::jsonb,3,'Mutual equal treatment.','original'),
('127.764.d.5.B',3,'A logistics officer plans how an embassy will buy fuel, furniture and services within budget and rules. This designs a program that:','["buys and sells goods and services for diplomatic operations", "runs a lemonade stand", "sells art at fairs", "stocks a school store"]'::jsonb,0,'Embassies need supply systems.','original'),
